#include "Combat/RPGCombatLibrary.h"
double URPGCombatLibrary::Mitigation(double Armor,double LevelK){ return FMath::Clamp(Armor/(Armor+FMath::Max(1.0,LevelK)),0.0,0.95); }
FRPGDamageResult URPGCombatLibrary::ResolveDamage(FRPGDamagePacket P,double Armor,double Resist,double CritChance,double CritMultiplier,double Accuracy,double Evasion,double LevelK){ FRPGDamageResult R; const double Hit=FMath::Clamp(Accuracy/FMath::Max(1.0,Accuracy+Evasion),0.05,0.95); R.Hit=Hit>=0.5; if(!R.Hit)return R; R.Critical=P.CanCrit && CritChance>0.5; double D=P.RawDamage*(R.Critical?CritMultiplier:1.0); if(P.DamageType==ERPGDamageType::Physical)D*=1.0-Mitigation(FMath::Max(0.0,Armor-P.Penetration),LevelK); else D*=1.0-FMath::Clamp(Resist-P.Penetration,0.0,0.95); R.FinalDamage=FMath::Max(0.0,D); return R; }
